import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { analyzeLockfile } from "./analyze.js";
import { parseLockfile } from "./parse/index.js";

// Real lockfiles generated by pnpm 9.15 (v9 format) and pnpm 8.15 (v6 format).
const V9 = readFileSync("test/fixtures/pnpm-v9.yaml", "utf8");
const V9_GIT = readFileSync("test/fixtures/pnpm-v9-git.yaml", "utf8");
const V6 = readFileSync("test/fixtures/pnpm-v6.yaml", "utf8");

describe("pnpm lockfiles", () => {
  it("parses v9, including scoped packages", () => {
    const lock = parseLockfile("pnpm-lock.yaml", V9);
    expect(lock.kind).toBe("pnpm");
    expect(lock.packages.get("lodash@4.17.21")?.integrity).toMatch(/^sha512-/);
    expect(lock.packages.get("@babel/code-frame@7.24.7")).toBeDefined();
    expect(lock.packages.get("@esbuild/darwin-arm64@0.25.10")?.name).toBe("@esbuild/darwin-arm64");
  });

  it("parses v6 keys and reads requiresBuild as an install script", () => {
    const lock = parseLockfile("pnpm-lock.yaml", V6);
    expect(lock.packages.get("lodash@4.17.21")).toBeDefined();
    expect(lock.packages.get("esbuild@0.19.12")?.hasInstallScript).toBe(true);
  });

  it("reads git dependencies (stored as source tarballs) and deprecations", () => {
    const lock = parseLockfile("pnpm-lock.yaml", V9_GIT);
    expect(lock.packages.get("is-odd@3.0.1")?.resolved).toMatch(/^https:\/\/codeload\.github\.com\//);
    expect(lock.packages.get("left-pad@1.3.0")?.deprecated).toMatch(/padStart/);
  });

  it("flags git and deprecated packages when they are introduced", () => {
    const report = analyzeLockfile("pnpm-lock.yaml", V9, V9_GIT)!;
    const rules = report.findings.map((f) => `${f.rule}:${f.package}`).sort();
    expect(rules).toContain("git-source:is-odd");
    expect(rules).toContain("deprecated:left-pad");
    expect(rules.some((r) => r.startsWith("untrusted-host"))).toBe(false);
  });

  it("catches a tampered integrity and an injected tarball URL", () => {
    const tampered = V9.replace(
      /(lodash@4\.17\.21:\n\s+resolution: )\{integrity: [^}]+\}/,
      "$1{integrity: sha512-AAAA, tarball: https://evil.example.com/lodash-4.17.21.tgz}",
    );
    expect(tampered).not.toBe(V9);
    const rules = analyzeLockfile("pnpm-lock.yaml", V9, tampered)!.findings.map((f) => f.rule).sort();
    expect(rules).toEqual(["integrity-changed", "source-changed"]);
  });

  it("rejects lockfiles older than v6 with a clear message", () => {
    expect(() => parseLockfile("pnpm-lock.yaml", "lockfileVersion: 5.4\npackages: {}\n")).toThrow(/pnpm 8/);
  });
});
